sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// 1. Define the 24-hour time window (24 hours * 3600 seconds)
    var hoursBack = 24;
    var gdt = new GlideDateTime();
    gdt.addSeconds(-(hoursBack * 3600));

    // 2. Query your custom table for existing requests
    var dupeCheck = new GlideRecord(current.getTableName()); // Dynamically uses current table
    dupeCheck.addQuery('requested_by', current.requested_by);       // Matches 'Requested By' field
    dupeCheck.addQuery('keyboard_model', current.keyboard_model); // Matches 'Keyboard Model' field
    dupeCheck.addQuery('laptop_model', current.laptop_model);     // Matches 'Laptop Model' field
    dupeCheck.addQuery('sys_created_on', '>=', gdt);              // Within last 24 hours

    dupeCheck.setLimit(1);
    dupeCheck.query();

    // 3. If a match is found, abort the insert
    if (dupeCheck.hasNext()) {
        current.setAbortAction(true);
        gs.addErrorMessage('Duplicate Request Blocked: You have already submitted a request for these exact items within the last 24 hours.');
    }

})(current, previous);
